package com.habitforge.forge;
import com.habitforge.forge.dto.*; import com.habitforge.forge.entity.Frequency; import com.habitforge.forge.repository.*; import com.habitforge.forge.service.HabitService; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class ForgeApplicationTests { @Autowired HabitRepository habits; @Autowired CompletionLogRepository logs; @Autowired StreakRepository streaks; @Autowired HabitService service; @BeforeEach void clean(){streaks.deleteAll();logs.deleteAll();habits.deleteAll();}
 @Test void streakBuilds(){var h=service.create(new HabitRequest("Read","20 pages",Frequency.DAILY,false,null));service.checkIn(h.id(),new CompletionRequest(LocalDate.now().minusDays(1),null));service.checkIn(h.id(),new CompletionRequest(LocalDate.now(),null));var s=service.streak(h.id());assertEquals(2,s.currentStreak());assertEquals(2,s.bestStreak());}
 @Test void duplicateRejected(){var h=service.create(new HabitRequest("Walk",null,Frequency.DAILY,false,null));service.checkIn(h.id(),new CompletionRequest(LocalDate.now(),null));assertThrows(RuntimeException.class,()->service.checkIn(h.id(),new CompletionRequest(LocalDate.now(),null)));}
 @Test void missedDayResetsCurrent(){var h=service.create(new HabitRequest("Study",null,Frequency.DAILY,false,null));service.checkIn(h.id(),new CompletionRequest(LocalDate.now().minusDays(3),null));service.checkIn(h.id(),new CompletionRequest(LocalDate.now().minusDays(2),null));var s=service.streak(h.id());assertEquals(0,s.currentStreak());assertEquals(2,s.bestStreak());}
}
